(4, 'Necklaces & Sets', 'necklaces-sets', 'Bridal Kundan chokers, temple haar sets, and delicate festive pendant collars.', '/images/categories/necklaces-sets.webp', '/images/categories/necklaces-sets.jpg', 'Grand Bridal Necklaces & Sets', 'Uncut kundan glass work embellished with semi-precious bead clusters', 4, 1, '2026-09-14 18:46:41', '2026-09-24 14:40:19', NULL, NULL),
(5, 'Earrings & Jhumkas', 'earrings-jhumkas', 'Antique peacock jhumkas, chandbalis, and shimmering contemporary ear drops.', '/images/categories/earrings-jhumkas.webp', '/images/categories/earrings-jhumkas.jpg', 'Artisan Jhumkas & Chandbalis', 'Lightweight all-day comfort with grand royal presence', 5, 1, '2026-09-14 18:46:41', '2026-09-24 14:40:19', NULL, NULL),
(6, 'Bangles', 'bangles', 'Sets of 2, 4 and bridal chooda imitation bangles in exquisite lattice patterns.', '/images/categories/bangles.webp', '/images/categories/bangles.jpg', 'Traditional Designer Bangles', 'Velvet-smooth inner contours with precision carved filigree', 6, 1, '2026-09-14 18:46:41', '2026-09-24 14:40:19', NULL, NULL),
(7, 'Mangalsutras', 'mangalsutras', 'Sacred black bead chains paired with auspicious wati, diamond, and floral pendants.', '/storage/products/mangalsutras/mgl_1-1.webp', '/storage/products/mangalsutras/mgl_1-1.webp', 'Auspicious 1 Gram Micro Gold Mangalsutras', 'Sacred black bead chains with 1 gram micro gold pendants crafted for everyday elegance.', 8, 1, '2026-09-14 18:46:41', '2026-09-24 13:38:35', NULL, NULL),
(8, 'Pendants', 'pendants', NULL, '/storage/products/pendants/pnd_001.webp', '/storage/products/pendants/pnd_001.webp', 'Royal 1 Gram Micro Gold Pendants', 'Intricately carved Om, Trishul, floral, and religious pendants with anti-tarnish micro gold finish.', 7, 1, '2026-09-14 18:46:41', '2026-09-24 13:38:35', NULL, NULL),
(9, 'Kadas', 'kadas', 'The Mens Kada', '/storage/categories/kadas_wear.webp', '/storage/categories/kadas_wear.webp', 'Imperial Rajwadi Gold Kadas', 'Heavy carved Bahubali, lion head, and royal filigree micro gold kadas.', 4, 1, '2026-09-15 11:05:05', '2026-09-24 13:38:35', NULL, NULL),
(10, 'Merrige & Navratri Special', 'merrige-navrati-special', 'Regal groom sherwani malas, multi-strand wedding haar, and festive Navratri collection in 1 gram micro gold.', '/storage/categories/mataji_haar_wear.webp', '/storage/categories/mataji_haar_wear.webp', 'Groom Wedding Malas & Sacred Mataji Haar', 'Regal multi-strand sherwani malas, bridal temple jewellery, and divine Mataji haar.', 5, 1, '2026-09-15 11:10:36', '2026-09-24 13:38:35', NULL, NULL),
(15, '2 Kaddi (Lucky)', '2-kaddi', 'Traditional Men 2-Kaddi double interlocking link chains and royal lucky bracelets in 1 gram micro gold.', '/storage/categories/kadi_wear.webp', '/storage/categories/kadi_wear.webp', 'Royal 2-Kaddi Luckies & Double Links', 'Authentic Gujarati 2-Kaddi interlocking craftsmanship finished with 24K micro gold plating.', 6, 1, '2026-09-24 13:38:35', '2026-09-24 13:38:35', NULL, NULL);
