INSERT INTO `reviews` (`id`, `product_id`, `user_id`, `customer_name`, `customer_email`, `rating`, `title`, `comment`, `is_verified_purchase`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 'Meenakshi Rathore', 'meenakshi@example.com', 5, 'Looks exactly like real Kundan!', 'I wore this Rajputana Choker set to my cousin’s wedding and received non-stop compliments. The green beads and gold finish look like pure 22k gold heirloom jewellery. Packaging was royal!', 1, 'approved', '2026-09-14 18:46:42', '2026-09-14 18:46:42'),
(2, 2, NULL, 'Vikramaditya Singh', 'vikram@example.com', 5, 'Solid weight and royal curb link polish', 'The curb link chain has genuine weight and high polish. Have been wearing it daily for 3 weeks and zero fading. Fast delivery to Udaipur.', 1, 'approved', '2026-09-14 18:46:42', '2026-09-14 18:46:42'),
(3, 3, NULL, 'Ananya Iyer', 'ananya@example.com', 5, 'Gorgeous temple jhumkas!', 'The peacock detailing is so sharp and clean. Very lightweight on the ears even though it looks very heavy. Worth every rupee.', 1, 'approved', '2026-09-14 18:46:42', '2026-09-14 18:46:42'),
(4, 5, NULL, 'Sunita Agarwal', 'sunita@example.com', 5, 'Perfect 2.6 size bangles', 'The 1 gram micro plating is so bright and rich. The floral laser cutwork is exquisite. Thank you Rayka Jewellery!', 1, 'approved', '2026-09-14 18:46:42', '2026-09-14 18:46:42'),
(5, 7, NULL, 'Rajveer Shekhawat', 'rajveer@example.com', 5, 'Lion Kada makes a bold statement', 'Awesome lion head carving with red ruby eyes. Sturdy spring mechanism makes it very easy to put on and take off. 10/10.', 1, 'approved', '2026-09-14 18:46:42', '2026-09-14 18:46:42'),
(6, 1531, 1, 'Rohan Panchal', 'admin@raykajewellery.com', 5, 'My Biskit Chain', 'Bhai product to ek dum mast che', 0, 'approved', '2026-09-16 05:50:10', '2026-09-16 05:50:21');
